<?php
namespace App\Http\Controllers\Api;
use App\Models\RfidCard;use App\Models\GateLog;use Illuminate\Http\Request;
class RfidController{private function device(Request $r){$key=$r->header('X-SmartGate-Device');abort_unless($key&&hash_equals((string)env('ESP32_DEVICE_KEY',''),$key),401);}public function scan(Request $r){$this->device($r);$d=$r->validate(['rfid_uid'=>'required','reader'=>'required|in:entry,exit','device_id'=>'nullable']);$ok=RfidCard::where('uid',strtoupper($d['rfid_uid']))->where('status','active')->exists();GateLog::create(['rfid_uid'=>strtoupper($d['rfid_uid']),'event_type'=>'rfid_scan','gate_status'=>$ok?'approved':'denied','source_device'=>'esp32-'.$d['reader'],'reader'=>$d['reader'],'log_notes'=>$ok?'RFID approved':'RFID denied']);return ['ok'=>true,'gate_opened'=>$ok,'gate_status'=>$ok?'approved':'denied','reader'=>$d['reader']];}public function events(Request $r){return GateLog::where('id','>',(int)$r->query('after_id',0))->where('event_type','rfid_scan')->orderBy('id')->limit(50)->get();}}
